import { BrowserRouter as Router, Routes, Route, Link } from 'react-router-dom';
import CandidateResumes from './components/CandidateResumes';

function Home() {
  return (
    <div style={{ padding: 40, fontFamily: 'Segoe UI, sans-serif' }}>
      <h1 style={{ color: '#6366f1' }}>Job Portal</h1>
      <nav style={{ display: 'flex', gap: 16, marginTop: 20 }}>
        <Link to="/candidates/resumes" style={{ color: '#6366f1', fontWeight: 600 }}>
          📄 Candidate Resumes
        </Link>
      </nav>
    </div>
  );
}

function App() {
  return (
    <Router>
      <Routes>
        <Route path="/" element={<Home />} />
        <Route path="/candidates/resumes" element={<CandidateResumes />} />
      </Routes>
    </Router>
  );
}

export default App;
